package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
final class MigrationRecoveryBrowserAcceptance {
 static void click(Page page,String label){ServiceOutagesBrowserAcceptance.click(page,label);}
 static void run(BrowserTest h)throws Exception{
  String record=id();ImportedJournalsAcceptance.seed(record,id(),id());MigrationSource.tables.get("incident").getFirst().put("priority","urgent");var plan=ImportedJournalsAcceptance.plan();
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   var page=context.newPage();h.login(page,"admin");page.navigate(h.base()+"/admin/migrations");TransferBrowserAcceptance.saved(page);page.locator("#migration-plan").fill(JSON.writeValueAsString(plan));page.locator("#migration-create button").click();TransferBrowserAcceptance.saved(page);String parent=page.locator("#migration-jobs").inputValue();page.locator("#migration-token").fill(MigrationSource.TOKEN);page.locator("#migration-fetch").click();assertThat(page.locator("#migration-report")).containsText("review");TransferBrowserAcceptance.saved(page);page.locator("#migration-preview").click();assertThat(page.locator("#migration-message")).containsText("Priority must be 1–5");int calls=MigrationSource.queries.size();page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Diagnose mappings and replay staging")).press("Enter");assertThat(page.locator("main")).containsText("mapping_error");var tables=object(plan.get("tables"));object(object(tables.get("incident")).get("values")).put("priority",map("urgent","3"));page.getByLabel("Source table mappings (JSON)").fill(JSON.writeValueAsString(tables));click(page,"Review corrected replay");assertThat(page.locator("main")).containsText("3 retained rows");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/migration-replay-review-light.png")).setFullPage(true));click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertEquals(true,page.evaluate("Array.from(document.querySelectorAll('main .panel')).every(e => e.scrollWidth <= e.clientWidth)"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/migration-replay-review-dark.png")).setFullPage(true));page.getByLabel("Create this exact corrected replay from retained staging").check();click(page,"Create corrected replay");assertThat(page.locator("main")).containsText("Corrected replay created");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Inspect corrected row diagnostics")).press("Enter");assertThat(page.locator("main")).containsText("mapping_valid");assertThat(page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Open original staged migration"))).hasAttribute("href","/admin/migrations/"+parent+"/recovery");String child=page.url().split("/")[5];page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/migration-replay-created-dark.png")).setFullPage(true));page.navigate(h.base()+"/admin/migrations");TransferBrowserAcceptance.saved(page);page.locator("#migration-jobs").selectOption(child);TransferBrowserAcceptance.saved(page);page.locator("#migration-preview").click();TransferBrowserAcceptance.saved(page);page.locator("#migration-apply").click();assertThat(page.locator("#migration-report")).containsText("\"preview\": false");assertEquals(calls,MigrationSource.queries.size());
   try(var db=h.store.open()){PlatformFoundationTest.bind(db);assertEquals("3",object(Service.record(db,"sc_request",record).get("data")).get("priority"));assertEquals("review",object(TransferJobs.job(db,parent).get("detail")).get("status"));assertEquals(3,db.count("SELECT COUNT(*) FROM os_transfer_item WHERE job_id=?",parent));}
  }finally{MigrationSource.reset();}
 }
}
